\[
\nabla\times\widetilde{\vec E}
=-\frac{\partial\widetilde{\vec B}}{\partial t},
\qquad
\nabla\times\widetilde{\vec B}
=\mu_0\widetilde\sigma\widetilde{\vec E}
+\mu_0\epsilon_0\frac{\partial\widetilde{\vec E}}{\partial t}.
\tag*{[1]}
\]

